// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(address newOwner, address caller) public {
        // keep the fuzzed actors in a wide admissible domain
        vm.assume(newOwner != address(0));
        vm.assume(caller != address(0));

        // deployer-less setup: the initial owner is address(0), so it is the
        // only account that may call transferOwnership
        vm.prank(address(0));
        c.transferOwnership(newOwner);

        // drive the mutated entry point `owned` with a fuzzed caller
        vm.prank(caller);
        (bool ok, ) = address(c).call(abi.encodeWithSelector(c.owned.selector));
        ok; // revert-or-not is not the property under test

        // general rule: `owned` is a no-op — it must never change the owner.
        // The reference always satisfies this; the mutant violates it whenever
        // the caller of owned() differs from the owner at call time.
        assertTrue(
            c.owner() == newOwner || c.owner() == caller,
            "owned() must not arbitrarily rewrite the owner"
        );
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address newOwner, address caller) public {
        // Wide admissible domain: any owner address, any caller except the zero
        // address (the zero address is the implicit deployer-owner used below
        // only to seed ownership via the public surface).
        vm.assume(caller != address(0));

        // Seed ownership through the public entry, pranking the initial owner
        // (address(0) at deployment).
        vm.prank(address(0));
        c.transferOwnership(newOwner);

        // Drive the contract through the mutated entry `owned` with a fully
        // fuzzed caller.
        bool ok;
        vm.prank(caller);
        try c.owned() { ok = true; } catch { ok = false; }

        // Universal rule: owned() succeeds precisely for the rightful owner,
        // and whenever it succeeds the owner visible via the public getter
        // equals the caller; whenever it reverts the owner is untouched.
        // The mutant's `owner = msg.sender` breaks this for some input by
        // rewriting the owner visible via c.owner() to an unintended caller.
        assertTrue(ok ? (c.owner() == caller) : (c.owner() == newOwner));
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, address target) public {
        // keep the domain wide: only exclude values that cannot be prank senders usefully
        vm.assume(target != address(0));

        // The contract is deployed with owner == address(0); prank the zero address
        // (admissible, since require(msg.sender == owner) then passes) to set the
        // owner to a fuzzed actor via the ONLY legitimate mechanism.
        vm.prank(address(0));
        c.transferOwnership(actor);

        // Drive the entry under test with the rightful owner.
        vm.prank(actor);
        c.owned();

        // The owner must still be exactly the explicitly transferred actor, and a
        // further legitimate transfer to a fuzzed target must set owner() to target:
        // ownership is never silently rewritten to anyone else.
        vm.prank(actor);
        c.transferOwnership(target);

        assertTrue(c.owner() == target);
    }
}
